import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const g=JSON.parse('{"title":"Customisation & white-label","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/13-customization.md","filePath":"generated/modules/13-customization.md","lastUpdated":null}'),n={name:"modules/13-customization.md"};function r(o,a,i,p,l,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="customisation-white-label" tabindex="-1">Customisation &amp; white-label <a class="header-anchor" href="#customisation-white-label" aria-label="Permalink to &quot;Customisation &amp; white-label&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 1 / 4 · <a href="/VendoraSystem-docs/specs/13-customization">spécification complète</a></span></p><p>Personnalisation de l&#39;apparence par magasin et par marque, de l&#39;écran de vente, des tickets, de la langue et du kiosque, via des design tokens partagés, sans jamais toucher au flux métier. Les fondations sont livrées : tokens consommés par Compose et SwiftUI, thème magasin et marque tenant avec héritage, logo et variante monochrome, configuration par appareil, langues fr / en / ar avec RTL sur les écrans cœur, boutons rapides et presets kiosque ; restent l&#39;éditeur visuel complet, les traductions des autres écrans, le layout par appareil, les images du kiosque et l&#39;app kiosque (phase 4).</p><div class="kpis"><div><b>20</b><span>faites</span></div><div><b>5</b><span>partielles</span></div><div><b>5</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="design-tokens" tabindex="-1">Design tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to &quot;Design tokens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Design tokens partagés</strong><br><span class="muted">Construire toute l&#39;UI des caisses depuis des tokens définis dans :shared (palettes clair / sombre, couleurs sémantiques non customisables, espacements, rayons, tailles, primaryText).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-04</td><td>1.x, UX1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-web">📷</a></td></tr><tr><td><strong>Contraste WCAG AA garanti</strong><br><span class="muted">Valider les couleurs saisies (#RRGGBB) et ajuster automatiquement le texte posé sur la primaire (blanc / noir, ratio ≥ 4,5:1) avec avertissement à l&#39;éditeur.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-03</td><td>1.x, UX8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux8-back-office-console">📷</a></td></tr><tr><td><strong>Tokens d&#39;espacement Android</strong><br><span class="muted">Remplacer les marges codées en dur des écrans Android par les tokens PosSpacing (xs 4 · s 8 · m 16 · l 24 · xl 32) issus de DesignTokenFactory.<br><i>116 dp remplacés dans 23 écrans ; restent les tailles fixes (icônes, boutons, colonnes), à migrer si la spec 13 définit les tokens correspondants.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-THEME-04</td><td>1.x, 2.27</td><td></td></tr><tr><td><strong>Mode clair / sombre / système</strong><br><span class="muted">Choisir le mode de couleur du magasin (LIGHT, DARK, SYSTEM) ; les caisses se recolorent sans redémarrage, panier conservé.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-02</td><td>1.x, 2.22, UX5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-logo-config-appareil">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux5b-listes-editeurs">📷</a></td></tr></tbody></table><h2 id="theme-magasin-marque" tabindex="-1">Thème magasin &amp; marque <a class="header-anchor" href="#theme-magasin-marque" aria-label="Permalink to &quot;Thème magasin &amp; marque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Thème du magasin (écran Apparence)</strong><br><span class="muted">Définir couleurs primaire / secondaire, mode et nom affiché du magasin avec un aperçu caisse live, puis publier une version (409 en cas d&#39;édition concurrente).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-01, RG-THEME-02</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-ios">📷</a></td></tr><tr><td><strong>Propagation du thème aux caisses</strong><br><span class="muted">Voir un thème publié au back-office appliqué sur toutes les caisses du magasin au pull suivant (≤ 36 s mesurés), sans réinstallation ni reconnexion.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-THEME-05</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-appairage-ios">📷</a></td></tr><tr><td><strong>Thème de marque du tenant (héritage)</strong><br><span class="muted">Définir une marque commune (couleurs, nom, logo) dont chaque magasin hérite champ par champ ; résolution appareil &gt; magasin &gt; marque &gt; preset &gt; défauts.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-06, RG-THEME-18</td><td>1.x, 2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Restauration de la version précédente</strong><br><span class="muted">Revenir en un clic à la version précédente du thème, propagée comme une publication normale.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-15</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-web">📷</a></td></tr><tr><td><strong>Journal d&#39;audit de la personnalisation</strong><br><span class="muted">Tracer chaque publication de thème, de marque, de configuration d&#39;appareil et de preset kiosque (qui, quoi, avant / après).<br><i>Audit STORE_THEME, BRAND_THEME, DEVICE_CONFIG, KIOSK_PRESET ; lot R8 : layouts de vente tracés à la création et à chaque publication (résumé avant / après : nom, rôle, défaut, version, pages, boutons), visibles dans le journal d&#39;audit.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-THEME-15</td><td>2.22, 2.25, R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8a-journal-inscription">📷</a></td></tr></tbody></table><h2 id="logo-assets" tabindex="-1">Logo &amp; assets <a class="header-anchor" href="#logo-assets" aria-label="Permalink to &quot;Logo &amp; assets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Logo du magasin et variante monochrome</strong><br><span class="muted">Téléverser un logo PNG / JPEG (≤ 2 Mo) ; le serveur dérive une variante couleur (≤ 512 px) et une variante monochrome tramée Floyd–Steinberg (≤ 384 points) pour l&#39;impression thermique.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-07</td><td>2.22</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-logo-config-appareil">📷</a></td></tr><tr><td><strong>Logo de marque hérité</strong><br><span class="muted">Téléverser un logo au niveau du tenant, hérité par les magasins sans logo propre et republié à toutes les caisses.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-17, RG-THEME-18</td><td>2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Cache local des assets et repli texte</strong><br><span class="muted">Afficher le logo hors ligne grâce au cache de l&#39;appareil, alimenté après chaque pull sans jamais bloquer ; sans logo, repli sur le nom commercial en texte.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-THEME-17</td><td>1.x, 2.22</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-logo-config-appareil">📷</a></td></tr><tr><td><strong>Logo sur les tickets</strong><br><span class="muted">Imprimer le logo monochrome en en-tête des tickets (GS v 0), nom en taille normale ; sans logo, nom en double taille.<br><i>Ticket de vente et d&#39;annulation seulement : pas de logo sur Z / X / bons cuisine ; ticket simulé avec logo non capturé (testé).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-THEME-07</td><td>2.22</td><td></td></tr></tbody></table><h2 id="langues" tabindex="-1">Langues <a class="header-anchor" href="#langues" aria-label="Permalink to &quot;Langues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Interface en français, anglais et arabe</strong><br><span class="muted">Utiliser les écrans cœur de la caisse (connexion, vente, encaissement, session, historique) en fr, en ou ar grâce à AppStrings partagé.<br><i>Lot R8d : back-office Angular en français, anglais et arabe — sélecteur dans la barre du haut et sur les pages d&#39;accès, choix gardé dans le navigateur ; ~1 450 textes. Lot UX restes (04-05/11/2026) : plus aucun texte français en dur sur les caisses iOS et Android (dialogues, écrans de session, retours, X / Z, inventaire, transferts, réglages imprimante, file d&#39;impression, diagnostic, réceptions, réseau du magasin, appairage, alertes) ; refus du moteur partagé et textes du matériel (statut d&#39;imprimante, erreurs Bluetooth / USB, verdicts du diagnostic) dans la langue de la caisse ; nombre de produits accordé en arabe ; erreurs de validation du serveur structurées et traduites au back-office (y compris les refus du catalogue) ; console Vendora en français, anglais et arabe. Restent en français, volontairement : écrans de développement, textes imprimés, rapport du diagnostic (protocole) et ce qui part au serveur.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-12</td><td>2.25, R8, UX-restes</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r8cd-images-langues">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-04-ux-restes-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-04-ux-restes-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-04-ux-restes-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-04-ux-restes-console">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-04-ux-restes-ios-reglages">📷</a></td></tr><tr><td><strong>Rendu RTL pour l&#39;arabe</strong><br><span class="muted">Passer l&#39;interface en droite-à-gauche quand la langue est ar, en gardant les montants en chiffres 0-9.<br><i>RTL sur Compose et SwiftUI ; lot R8d : back-office Angular en arabe de droite à gauche (dir/lang posés sur la page, styles en propriétés logiques sur toutes les pages), montants en chiffres 0-9. Lot UX restes : console Vendora en arabe (RTL) ; montants, numéros, dates et noms latins isolés en LTR dans les phrases arabes des caisses et de la console ; iOS : historique, X, Z et archive en miroir, stepper − n + dans l&#39;ordre d&#39;une droite numérique. Reste : parité du stepper avec Android (en miroir) à trancher.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-12</td><td>2.25, R8, UX5, UX8, UX-restes</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r8cd-images-langues">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux5a-rapports-reglages">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux8-back-office-console">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-04-ux-restes-console">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-04-ux-restes-ios-reglages">📷</a></td></tr><tr><td><strong>Langue du magasin et surcharge par appareil</strong><br><span class="muted">Choisir la langue des caisses du magasin et la surcharger par appareil ; résolution appareil &gt; magasin &gt; fr, langue invalide refusée (422).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-13</td><td>2.22, 2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr></tbody></table><h2 id="configuration-par-appareil" tabindex="-1">Configuration par appareil <a class="header-anchor" href="#configuration-par-appareil" aria-label="Permalink to &quot;Configuration par appareil&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Configuration par appareil</strong><br><span class="muted">Surcharger pour un appareil précis le mode de couleur (ex. KDS toujours sombre), la langue, le preset kiosque et l&#39;écran d&#39;accueil d&#39;une caisse (automatique selon le profil, tables ou vente directe), publication versionnée (409) et appliquée au pull suivant ; le profil du magasin part à l&#39;appairage et à chaque changement.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-06</td><td>2.22, 2.25, Accès aux tables</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-logo-config-appareil">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-acces-tables">📷</a></td></tr><tr><td><strong>Layout de vente par appareil</strong><br><span class="muted">Assigner un layout de boutons rapides différent à un appareil via sa configuration.<br><i>Reste explicite des lots 2.22 et 2.25 (aujourd&#39;hui : un layout par défaut par magasin et rôle).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-THEME-06, RG-THEME-08</td><td></td><td></td></tr></tbody></table><h2 id="ecran-de-vente" tabindex="-1">Écran de vente <a class="header-anchor" href="#ecran-de-vente" aria-label="Permalink to &quot;Écran de vente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Boutons rapides (SalesLayout)</strong><br><span class="muted">Composer l&#39;écran de vente en pages de boutons rapides sur une grille (≤ 8×8), tailles 1×1 / 2×1 / 2×2, cibles produit / catégorie / page, couleur optionnelle, reçues par les caisses au pull.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-08</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-web">📷</a></td></tr><tr><td><strong>Boutons orphelins masqués</strong><br><span class="muted">Masquer à la vente un bouton dont le produit ou la catégorie est supprimé ou désactivé, et le signaler en rouge dans l&#39;éditeur.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-09</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-web">📷</a></td></tr><tr><td><strong>Noms longs sur les boutons 1×1</strong><br><span class="muted">Afficher les noms longs sur deux lignes avec un corps réduit au-delà de 11 caractères au lieu de les tronquer.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td></td><td>2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a></td></tr><tr><td><strong>Presets d&#39;UI par profil de magasin</strong><br><span class="muted">Partir d&#39;un preset de thème et de layout selon le profil (RESTAURANT, GROCERY, APPAREL, SERVICE, GENERIC), y compris création d&#39;un layout « depuis un preset ».<br><i>Presets de couleurs et de layout faits ; comportements d&#39;accueil par profil (plan de tables en écran d&#39;accueil, scan en focus permanent…) non tracés comme faits — la notion de module tables par profil reste à faire.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-10</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-web">📷</a></td></tr><tr><td><strong>Éditeur de l&#39;écran de vente</strong><br><span class="muted">Éditer la grille au back-office : ajout / édition / suppression de boutons, pages, layout par défaut, publication versionnée (409 sans merge), orphelins en rouge.<br><i>Éditeur minimal ; drag &amp; drop, redimensionnement, recherche à glisser et « repartir du preset » relèvent de l&#39;éditeur visuel (phase 4) ; publication / 409 / orphelin non capturés sur la vraie stack ; publications tracées au journal d&#39;audit (lot R8), pas de restauration d&#39;une version.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td>RG-THEME-08, RG-THEME-09</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-web">📷</a></td></tr></tbody></table><h2 id="tickets" tabindex="-1">Tickets <a class="header-anchor" href="#tickets" aria-label="Permalink to &quot;Tickets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Zones de branding des tickets</strong><br><span class="muted">Éditer l&#39;en-tête et le pied du ticket (message, mentions légales, réseaux sociaux, QR du reçu digital) avec aperçu 80 mm, sans toucher au corps.<br><i>Phase 4 — ReceiptTemplate (spec 11) non édité ; seuls le logo et le nom commercial (ou de marque) sont posés en en-tête.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-THEME-11, RG-THEME-16</td><td></td><td></td></tr></tbody></table><h2 id="kiosque" tabindex="-1">Kiosque <a class="header-anchor" href="#kiosque" aria-label="Permalink to &quot;Kiosque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Presets kiosque (configuration)</strong><br><span class="muted">Configurer au back-office les presets kiosque du magasin : texte d&#39;accueil, jusqu&#39;à 5 bannières avec période de validité, produits mis en avant, parcours de paiement et délai d&#39;inactivité.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-14</td><td>2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Preset kiosque par appareil</strong><br><span class="muted">Assigner un preset kiosque à un appareil via sa configuration (422 si le preset n&#39;existe pas dans le magasin).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-06, RG-THEME-14</td><td>2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Images des bannières et de l&#39;écran d&#39;accueil</strong><br><span class="muted">Téléverser les visuels des bannières et de l&#39;écran d&#39;accueil du kiosque.<br><i>Reste du lot 2.25 (bannières configurées par titre, cible et validité, sans image).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-THEME-14, RG-THEME-17</td><td></td><td></td></tr><tr><td><strong>Kiosque white-label</strong><br><span class="muted">Afficher sur le kiosque l&#39;écran d&#39;accueil aux couleurs du magasin, le carrousel de bannières valides et les produits mis en avant.<br><i>Phase 4 — l&#39;app kiosque consommera KioskPresetRepository.assigned() (miroir local déjà en place).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-THEME-14</td><td></td><td></td></tr></tbody></table><h2 id="editeurs-visuels" tabindex="-1">Éditeurs visuels <a class="header-anchor" href="#editeurs-visuels" aria-label="Permalink to &quot;Éditeurs visuels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Éditeur de thème complet</strong><br><span class="muted">Prévisualiser en direct caisse, kiosque et ticket avec le thème en cours d&#39;édition.<br><i>Phase 4 — l&#39;aperçu actuel ne montre que la caisse.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td></td><td></td><td></td></tr></tbody></table><h2 id="mise-en-page" tabindex="-1">Mise en page <a class="header-anchor" href="#mise-en-page" aria-label="Permalink to &quot;Mise en page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Mise en page tablette (iPad, tablettes Android)</strong><br><span class="muted">Caisse en deux colonnes (catalogue | panier et paiement), plan de salle et addition côte à côte, feuilles en panneaux, KDS en paysage verrouillable.<br><i>Lot T : le téléphone reste pris en charge (serveurs, caisse mobile) ; à partir de 700 dp / pt (iPad, tablettes Android) : caisse en deux colonnes (catalogue | panier et paiement), plan de salle et addition côte à côte, rapports X / Z en panneaux centrés (le paiement et les feuilles iOS l&#39;étaient déjà), écran cuisine en paysage verrouillable (« Paysage 🔒 », verrouillé par défaut sur tablette). Seuils communs dans le moteur partagé (AdaptiveLayout). Prouvé sur tablette Android ; iOS fait et testé, preuve iPad à faire. Android 16 sur grand écran : le verrou paysage exige que l&#39;appareil autorise l&#39;orientation des apps (réglage « Format » de l&#39;app ou flotte gérée).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td></td><td>T</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-t-tablette">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Traduire les autres écrans des caisses (réglages, diagnostics, restaurant, messages du moteur) ; back-office : textes venus du serveur et textes composés (le reste est traduit, lot R8d).</li><li>Layout de vente assignable par appareil.</li><li>Logo sur les tickets Z / X / bons cuisine ; édition des zones de branding du ticket (ReceiptTemplate, phase 4).</li><li>Téléversement des images de bannières et d&#39;écran d&#39;accueil ; app kiosque white-label (phase 4).</li><li>Éditeur visuel complet de l&#39;écran de vente (drag &amp; drop) et du thème (aperçus kiosque / ticket) — phase 4.</li><li>Restauration d&#39;une version antérieure d&#39;un layout de vente (l&#39;audit est fait, lot R8).</li><li>Migrer les tailles fixes Android (icônes, colonnes) vers des tokens si la spec les définit.</li><li>Purge des anciens brand_assets côté serveur.</li><li>Acter dans la spec 13 le remplacement de BrandThemeUpdated par la re-publication des StoreThemeUpdated ; vérifier à l&#39;écran la bascule SYSTEM en direct.</li></ul>',26)])])}const b=t(n,[["render",r]]);export{g as __pageData,b as default};
